def dihedral(S):
 out=[]
 for refl in [False,True]:
  s={(r,-c if refl else c) for r,c in S}
  for k in range(4):
   q=s
   for _ in range(k): q={(c,-r) for r,c in q}
   minr=min(r for r,c in q); minc=min(c for r,c in q)
   out.append({(r-minr,c-minc) for r,c in q})
 return out
